<script setup lang="ts">
import { computed, ref } from 'vue'
import { BookOpen, PenLine, Headphones, MessageSquareText, RotateCcw, CircleCheck, Info } from 'lucide-vue-next'
import SectionHeader from '../components/common/SectionHeader.vue'
import { useAppState } from '../composables/useAppState'
const tabs=[{id:'reading',label:'IELTS Reading',icon:BookOpen},{id:'writing',label:'IELTS Writing',icon:PenLine},{id:'listening',label:'IELTS Listening',icon:Headphones},{id:'interview',label:'Interview Practice',icon:MessageSquareText}]
const active=ref('reading'),answer=ref(''),response=ref(''),submitted=ref(false); const { practiceResult, toast }=useAppState()
const prompt=computed(()=>({reading:'A university scholarship committee values applicants who demonstrate sustained service over isolated volunteering. Which statement best summarizes this?',writing:'Some students choose a degree for career stability, while others prioritize social impact. Discuss both views and give your opinion.',listening:'Demo transcript: The information session has moved from Hall B to the library auditorium and will begin at 3:30 PM. Where and when is the session?',interview:'Tell us about a time you led people through uncertainty. What did you do, and what changed as a result?'}[active.value]))
const submit=()=>{if(!answer.value&&!response.value)return;submitted.value=true;const score=active.value==='reading'?(answer.value==='sustained'?100:50):active.value==='listening'?(response.value.toLowerCase().includes('library')&&response.value.includes('3:30')?100:70):84;practiceResult.value={type:active.value,score,completedAt:new Date().toISOString(),explanation:'This is predetermined demo feedback, not an official assessment.'};toast('Your unofficial practice result is ready.')}
const reset=()=>{answer.value='';response.value='';submitted.value=false}
</script>
<template><main><section class="border-b border-slate-200 bg-gradient-to-b from-[#eff8ff] to-white py-18"><div class="container"><SectionHeader eyebrow="Practice with purpose" title="Prepare for tests and interviews" body="Try short original exercises, submit a response, and see clear mock explanations. Results are unofficial and never sent anywhere."/></div></section><section class="section pt-12"><div class="container max-w-5xl"><div class="flex gap-2 overflow-x-auto pb-2" role="tablist"><button v-for="tab in tabs" :key="tab.id" class="flex shrink-0 items-center gap-2 rounded-xl px-4 py-3 text-sm font-extrabold" :class="active===tab.id?'bg-[#5b45f5] text-white':'bg-slate-100 text-slate-600'" role="tab" :aria-selected="active===tab.id" @click="active=tab.id;reset()"><component :is="tab.icon" :size="17"/>{{ tab.label }}</button></div><div class="mt-7 grid gap-7 lg:grid-cols-[1.1fr_.9fr]"><section class="card p-7 sm:p-9"><div class="flex items-center justify-between"><span class="badge">Original mock question</span><span class="text-xs font-bold text-slate-400">1 of 1</span></div><h1 class="mt-7 text-2xl font-extrabold leading-snug text-[#17136b]">{{ prompt }}</h1><div v-if="active==='reading'" class="mt-7 grid gap-3"><label v-for="option in [{v:'isolated',t:'One impressive activity is always more valuable.'},{v:'sustained',t:'Long-term service can show deeper commitment.'},{v:'academic',t:'Only academic results matter to committees.'}]" :key="option.v" class="flex cursor-pointer gap-3 rounded-xl border border-slate-200 p-4"><input v-model="answer" type="radio" :value="option.v" class="mt-1 accent-[#5b45f5]"><span class="font-semibold text-[#17136b]">{{ option.t }}</span></label></div><textarea v-else v-model="response" class="field mt-7 min-h-56 resize-y leading-7" :placeholder="active==='listening'?'Type the location and time…':'Write your response here…'"/><div class="mt-7 flex flex-col gap-3 sm:flex-row"><button class="btn-primary" @click="submit">Submit response</button><button class="btn-secondary" @click="reset"><RotateCcw :size="16"/>Reset</button></div></section><aside class="card p-7 sm:p-9"><div v-if="!submitted" class="grid min-h-[360px] place-items-center text-center"><div><Info class="mx-auto text-slate-300" :size="34"/><h2 class="mt-5 text-xl font-extrabold text-[#17136b]">Your result will appear here</h2><p class="mt-2 text-sm leading-6 text-slate-500">Answer the question and submit when you’re ready.</p></div></div><div v-else><CircleCheck class="text-emerald-500" :size="30"/><p class="mt-6 text-xs font-bold uppercase tracking-wider text-slate-400">Unofficial practice score</p><p class="mt-2 text-6xl font-extrabold text-[#5b45f5]">{{ practiceResult?.score }}<span class="text-xl text-slate-400">%</span></p><h2 class="mt-7 text-lg font-extrabold text-[#17136b]">Mock explanation</h2><p class="mt-3 leading-7 text-slate-500">{{ active==='reading'?'The passage contrasts sustained service with isolated volunteering, so the long-term commitment answer is the closest summary.':active==='listening'?'The key details are “library auditorium” and “3:30 PM.” Listening for location changes is a common comprehension task.':'Your response has a clear example and reflective structure. Strengthen it with one measurable outcome and a more concise closing sentence.' }}</p><div class="mt-6 rounded-xl bg-amber-50 p-4 text-xs leading-5 text-amber-800">This result is a product simulation, not an official IELTS band or professional assessment.</div></div></aside></div></div></section></main></template>
